export type RegistrationDraft={profession:string;contact:string;direction:string;city:string;workTypes:string};
export type RegistrationPayload=Record<string,string|string[]|null>;

// Exact existing database columns. id and created_at are generated by Supabase.
export function mapRegistration(draft:RegistrationDraft):RegistrationPayload {
 const contact=draft.contact.trim();
 const valid=contact.includes('@')?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact):/^\+?[\d\s()-]+$/.test(contact)&&contact.replace(/\D/g,'').length>=7&&contact.replace(/\D/g,'').length<=15;
 if(!valid)throw new Error('请填写有效的手机号或邮箱。');
 if(!draft.profession.trim()||!draft.direction.trim()||!draft.workTypes.trim())throw new Error('请填写职业、职业方向和工作方式。');
 return {'联系方式':contact,'城市':draft.city.trim(),'职业':draft.profession.trim(),'职业方向':draft.direction.trim(),'工作方式':draft.workTypes.trim()};
}

export class RegistrationError extends Error {
 detail:unknown;
 constructor(message:string,detail:unknown){super(message);this.detail=detail}
}
export async function insertRegistration(payload:RegistrationPayload,config:{url:string;key:string},send:typeof fetch=fetch){
 if(!config.url||!config.key.startsWith('sb_publishable_'))throw new RegistrationError('注册服务暂未配置完成，请稍后再试。',{code:'CONFIGURATION_MISSING'});
 let response:Response;
 try{response=await send(new URL('/rest/v1/'+encodeURIComponent('FlowIn registrations'),config.url),{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(payload)})}
 catch(e){throw new RegistrationError('网络连接异常，暂时无法确认提交结果，请先勿重复提交，稍后联系管理员确认。',e)}
 if(response.ok)return {status:response.status};
 let detail:unknown;try{detail=await response.json()}catch{detail={status:response.status}}
 const code=(detail as {code?:string})?.code;
 const message=code==='23505'?'这份注册信息已提交，请勿重复提交。':response.status===401||response.status===403?'注册暂未开放提交权限，请联系管理员。':response.status===429?'提交过于频繁，请稍后再试。':response.status>=500?'注册服务暂时不可用，请稍后重试。':'注册信息未能提交，请检查填写内容或联系管理员。';
 throw new RegistrationError(message,{status:response.status,...(typeof detail==='object'&&detail!==null?detail:{response:detail})});
}
